// Interrupted fades resume from their current opacity; only the latest content wins.
const contentFades=new Map();
function fadeSwap(elements,update,enabled=true){
 const key=elements[0];if(!key){update();return}
 const previous=contentFades.get(key);
 const opacities=elements.map(el=>getComputedStyle(el).opacity);
 if(previous){contentFades.delete(key);previous.animations.forEach(a=>a.cancel())}
 if(!enabled||reduced.matches||!key.animate){update();return}
 const state={animations:[],update};contentFades.set(key,state);
 state.animations=elements.map((el,i)=>el.animate([{opacity:opacities[i]},{opacity:0}],{duration:180,easing:'ease-out',fill:'forwards'}));
 Promise.all(state.animations.map(a=>a.finished)).then(()=>{
  if(contentFades.get(key)!==state)return;
  update();state.animations.forEach(a=>a.cancel());
  state.animations=elements.map(el=>el.animate([{opacity:0},{opacity:1}],{duration:360,easing:'cubic-bezier(.22,.65,.2,1)',fill:'forwards'}));
  return Promise.all(state.animations.map(a=>a.finished)).then(()=>{if(contentFades.get(key)===state){contentFades.delete(key);state.animations.forEach(a=>a.cancel())}});
 }).catch(()=>{});
}
