$$('a[href^="#"]').forEach(a=>a.addEventListener('click',e=>{const target=document.getElementById(a.hash.slice(1));if(!target)return;e.preventDefault();cancelAnimationFrame(scrollAnimation);if(reduced.matches){target.scrollIntoView();scrollAnimation=0;return}const start=scrollY,end=target.getBoundingClientRect().top+scrollY-20,t0=performance.now();document.documentElement.style.scrollBehavior='auto';const tick=t=>{const p=Math.min(1,(t-t0)/750),ease=p<.5?4*p*p*p:1-Math.pow(-2*p+2,3)/2;window.scrollTo(0,start+(end-start)*ease);if(p<1)scrollAnimation=requestAnimationFrame(tick);else{scrollAnimation=0;document.documentElement.style.scrollBehavior='';target.setAttribute('tabindex','-1');target.focus({preventScroll:true})}};scrollAnimation=requestAnimationFrame(tick)}));
