function validate(){const errors={};const name=$('#name').value.trim(),digits=$('#phone').value.replace(/\D/g,''),date=$('#date').value;if(name.length<2)errors.name='Введите имя — не менее двух символов.';if(!/^[78]\d{10}$/.test(digits))errors.phone='Введите российский номер: +7 и ещё 10 цифр.';if(!date||!/^\d{4}-\d{2}-\d{2}$/.test(date)||date<today())errors.date='Выберите сегодняшнюю или будущую дату.';if(!$('#consent').checked)errors.consent='Подтвердите согласие с условиями обработки данных.';['name','phone','date','consent'].forEach(id=>{$('#'+id+'-error').textContent=errors[id]||'';$('#'+id).setAttribute('aria-invalid',String(Boolean(errors[id])))});return {errors,payload:{name,phone:'+7'+digits.slice(1),date,plot:tourPlot?.id||null,consent:$('#consent').checked}}}
